import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("returns an empty grid for an empty grid — [] → []");
  it.todo("kills a single live cell with no neighbors — [(0,0)] → []");
  it.todo(
    "Rule 1 Underpopulation: kills two adjacent cells each having 1 neighbor — [(0,1),(1,1)] → []",
  );
  it.todo(
    "Rule 2 Survival: a live cell with 3 live neighbors lives on — [(0,0),(1,0),(2,0),(1,2)] → next generation contains (1,1)... wait",
  );
  it.todo(
    "Rule 3 Overpopulation: a live cell with 4 live neighbors dies — center (1,1) absent from next generation",
  );
  it.todo(
    "Rule 4 Reproduction: a dead cell with exactly 3 live neighbors becomes alive — (1,1) present in next generation",
  );
  it.todo(
    "Block still life stays unchanged — [(0,0),(1,0),(0,1),(1,1)] → same 4 cells",
  );
  it.todo(
    "Blinker oscillates from vertical to horizontal — [(0,0),(0,1),(0,2)] → [(-1,1),(0,1),(1,1)]",
  );
  it.todo(
    "Blinker oscillates back to vertical after two generations — [(-1,1),(0,1),(1,1)] → [(0,0),(0,1),(0,2)]",
  );
  it.todo(
    "handles negative coordinates on an infinite grid — blinker at negative coordinates oscillates",
  );
});

