input.new_string:
export function nextGeneration(cells: Cell[]): Cell[] {
  return cells.filter(([x, y]) => {
    const neighborCount = cells.filter(
      ([otherX, otherY]) =>
        Math.abs(otherX - x) <= 1 &&
        Math.abs(otherY - y) <= 1 &&
        !(otherX === x && otherY === y),
    ).length;
    return neighborCount === 2 || neighborCount === 3;
  });
}

