function isNeighborOf([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  const isSameCell = otherX === x && otherY === y;
  return (
    !isSameCell && Math.abs(otherX - x) <= 1 && Math.abs(otherY - y) <= 1
  );
}

function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
  return liveCells.filter((other) => isNeighborOf(cell, other)).length;
}

export function nextGeneration(cells: Cell[]): Cell[] {
  return cells.filter((cell) => {
    const liveNeighbors = countLiveNeighbors(cell, cells);
    return liveNeighbors === 2 || liveNeighbors === 3;
  });
}

