import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it("returns an empty grid for an empty grid — [] → []", () => {
    expect(nextGeneration([])).toEqual([]);
  });
  it("Single cell dies: [(0,0)] → []", () => {
    expect(nextGeneration([[0, 0]])).toEqual([]);
  });
  it("Rule 1 Underpopulation: each cell has 1 neighbor and dies — [(0,1),(1,1)] → []", () => {
    expect(
      nextGeneration([
        [0, 1],
        [1, 1],
      ]),
    ).toEqual([]);
  });
  it("Rule 2 Survival: a live cell with 3 live neighbors lives on — (1,1) is in the next generation of [(0,0),(1,0),(2,0),(1,1)]", () => {
    const result = nextGeneration([
      [0, 0],
      [1, 0],
      [2, 0],
      [1, 1],
    ]);
    expect(result).toContainEqual([1, 1]);
  });
  it.todo(
    "Rule 2 Survival: a live cell with 2 live neighbors lives on — (0,1) is in the next generation of [(0,0),(0,1),(0,2)]",
  );
  it.todo(
    "Rule 3 Overpopulation: a live cell with 4 live neighbors dies — (1,1) is not in the next generation of [(0,0),(1,0),(2,0),(1,1),(0,2),(1,2),(2,2)]",
  );
